import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { MapaSchema, type Mapa } from '../contracts/mapa';

// Validates `assets/map/mapa.json` (generated by `node scripts/build-map.mjs`) against the zod contract
// and checks walkability: everything must be reachable from the Reception entrance (BFS, 4 directions).

const readJson = (relative: string): unknown =>
  JSON.parse(readFileSync(new URL(relative, import.meta.url), 'utf8'));

const raw = readJson('../../../assets/map/mapa.json');
const parsed = MapaSchema.safeParse(raw);
const map: Mapa = parsed.success ? parsed.data : (raw as Mapa);

type Tile = readonly [number, number];
const key = (x: number, y: number): string => `${x},${y}`;

const bytes = Buffer.from(map.collision, 'base64');
/** Collision bitset is LSB-first: bit (y * cols + x) is in byte (i >> 3), mask 1 << (i & 7). */
const isBlocked = (x: number, y: number): boolean => {
  const i = y * map.cols + x;
  return (((bytes[i >> 3] ?? 0) >> (i & 7)) & 1) === 1;
};
const isWalkable = (x: number, y: number): boolean =>
  x >= 0 && y >= 0 && x < map.cols && y < map.rows && !isBlocked(x, y);

function reachableFrom(start: Tile): Set<string> {
  const seen = new Set<string>();
  if (!isWalkable(start[0], start[1])) return seen;
  const queue: Tile[] = [start];
  seen.add(key(start[0], start[1]));
  for (let head = 0; head < queue.length; head++) {
    const [x, y] = queue[head] as Tile;
    for (const [dx, dy] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ] as const) {
      const nx = x + dx;
      const ny = y + dy;
      if (isWalkable(nx, ny) && !seen.has(key(nx, ny))) {
        seen.add(key(nx, ny));
        queue.push([nx, ny]);
      }
    }
  }
  return seen;
}

const entranceDoor = map.doors.find((d) => d.id === map.spawn.entrance);
const entranceTile: Tile = (entranceDoor?.tiles[0] as Tile | undefined) ?? [0, 0];
const reachable = reachableFrom(entranceTile);

function duplicates(ids: readonly string[]): string[] {
  const seen = new Set<string>();
  const dup = new Set<string>();
  for (const id of ids) (seen.has(id) ? dup : seen).add(id);
  return [...dup];
}

function collectDeskIds(node: unknown, out: string[] = []): string[] {
  if (Array.isArray(node)) node.forEach((n) => collectDeskIds(n, out));
  else if (node && typeof node === 'object') {
    for (const [k, v] of Object.entries(node)) {
      if (k === 'desk' && typeof v === 'string') out.push(v);
      else collectDeskIds(v, out);
    }
  }
  return out;
}

describe('assets/map/mapa.json', () => {
  it('CA-11: validates against the mapa/v1 contract (64x52 tiles)', () => {
    expect(
      parsed.success
        ? ''
        : parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('\n'),
    ).toBe('');
    expect(map.cols).toBe(64);
    expect(map.rows).toBe(52);
    expect(map.tileSize).toBe(16);
  });

  it('CA-11: every fixed room is present (incl. 4 project slots, corridor, servers, SOC)', () => {
    const ids = new Set(map.rooms.map((r) => r.id));
    const required = [
      'DIR',
      'REU',
      'PLN',
      'ENG',
      'QUA',
      'SOC',
      'ENT',
      'BIB',
      'REC',
      'COP',
      'WC',
      'TER',
      'SRV',
      'COR1',
      'COR2',
      'COR3',
      'PRJ1',
      'PRJ2',
      'PRJ3',
      'PRJ4',
    ];
    for (const id of required) expect(ids.has(id), `missing room ${id}`).toBe(true);
    expect(map.projectSlots.map((p) => p.room)).toEqual(['PRJ1', 'PRJ2', 'PRJ3', 'PRJ4']);
    for (const p of map.projectSlots) expect(p.seats).toHaveLength(6);
  });

  it('CA-11: ids are unique (rooms, doors, desks+seats, POIs, windows, lights, objects, zones)', () => {
    expect(duplicates(map.rooms.map((r) => r.id))).toEqual([]);
    expect(duplicates(map.doors.map((d) => d.id))).toEqual([]);
    expect(duplicates([...map.desks.map((d) => d.id), ...map.seats.map((s) => s.id)])).toEqual([]);
    expect(duplicates(map.pois.map((p) => p.id))).toEqual([]);
    expect(duplicates(map.windows.map((w) => w.id))).toEqual([]);
    expect(duplicates(map.lights.map((l) => l.id))).toEqual([]);
    expect(duplicates(map.objects.map((o) => o.id))).toEqual([]);
    expect(duplicates(map.lightZones.map((z) => z.id))).toEqual([]);
  });

  it('CA-11: cross references resolve (room doors, light zones, project seats, spawn ids)', () => {
    const rooms = new Set(map.rooms.map((r) => r.id));
    const doors = new Set(map.doors.map((d) => d.id));
    const zones = new Set(map.lightZones.map((z) => z.id));
    const seatIds = new Set([...map.desks.map((d) => d.id), ...map.seats.map((s) => s.id)]);
    const poiIds = new Set(map.pois.map((p) => p.id));
    for (const r of map.rooms) {
      for (const d of r.doors) expect(doors.has(d), `room ${r.id} door ${d}`).toBe(true);
      if (r.lightZone) expect(zones.has(r.lightZone), `room ${r.id} zone`).toBe(true);
    }
    for (const z of map.lightZones)
      for (const r of z.rooms) expect(rooms.has(r), `zone ${z.id} room ${r}`).toBe(true);
    for (const l of map.lights) expect(zones.has(l.zone), `light ${l.id}`).toBe(true);
    for (const p of map.projectSlots)
      for (const s of p.seats) expect(seatIds.has(s), `slot seat ${s}`).toBe(true);
    for (const id of [...map.spawn.provisionalDesks, ...map.spawn.freelancerSofa]) {
      expect(seatIds.has(id), `spawn ${id}`).toBe(true);
    }
    expect(map.spawn.approvalQueue.length).toBeLessThanOrEqual(8);
    for (const id of map.spawn.approvalQueue) expect(poiIds.has(id), `queue ${id}`).toBe(true);
    expect(doors.has(map.spawn.entrance)).toBe(true);
  });

  it('CA-11: 2 north face rows of each faced room are blocked (except doors)', () => {
    const doorTiles = new Set(map.doors.flatMap((d) => d.tiles.map(([x, y]) => key(x, y))));
    for (const r of map.rooms) {
      if (!r.faceRows) continue;
      for (const [x1, y1, x2] of r.rects) {
        for (let y = y1; y < y1 + r.faceRows; y++) {
          for (let x = x1; x <= x2; x++) {
            if (!doorTiles.has(key(x, y)))
              expect(isBlocked(x, y), `${r.id} face (${x},${y})`).toBe(true);
          }
        }
      }
    }
  });

  it('CA-11: no desk or seat sits on a collision tile; desk tables are blocked and never cover a seat', () => {
    const seatTiles = new Set<string>();
    for (const d of map.desks) {
      expect(isBlocked(d.seat[0], d.seat[1]), `desk ${d.id} seat is blocked`).toBe(false);
      seatTiles.add(key(d.seat[0], d.seat[1]));
    }
    for (const s of map.seats) {
      expect(isBlocked(s.tile[0], s.tile[1]), `seat ${s.id} is blocked`).toBe(false);
      seatTiles.add(key(s.tile[0], s.tile[1]));
    }
    for (const d of map.desks) {
      if (!d.table) continue;
      const [x1, y1, x2, y2] = d.table;
      for (let y = y1; y <= y2; y++) {
        for (let x = x1; x <= x2; x++) {
          expect(isBlocked(x, y), `desk ${d.id} table (${x},${y}) is walkable`).toBe(true);
          expect(seatTiles.has(key(x, y)), `desk ${d.id} table covers a seat at (${x},${y})`).toBe(
            false,
          );
        }
      }
    }
  });

  it('CA-11: every desk, seat, POI tile and door is reachable by BFS from the Reception entrance', () => {
    expect(reachable.size, 'entrance tile must be walkable').toBeGreaterThan(0);
    const unreachable: string[] = [];
    const check = (label: string, [x, y]: Tile): void => {
      if (!reachable.has(key(x, y))) unreachable.push(`${label} (${x},${y})`);
    };
    for (const d of map.desks) check(`desk ${d.id}`, d.seat);
    for (const s of map.seats) check(`seat ${s.id}`, s.tile);
    for (const p of map.pois) p.tiles.forEach((t) => check(`poi ${p.id}`, t));
    for (const d of map.doors) d.tiles.forEach((t) => check(`door ${d.id}`, t));
    for (const [name, tile] of [['receptionCounter', map.spawn.receptionCounter]] as const)
      check(name, tile);
    for (const [name, tile] of Object.entries(map.pets.beds)) check(`pet bed ${name}`, tile);
    expect(unreachable).toEqual([]);
  });

  it('CA-11: every room has at least one reachable walkable tile', () => {
    for (const r of map.rooms) {
      let found = false;
      for (const [x1, y1, x2, y2] of r.rects) {
        for (let y = y1; y <= y2 && !found; y++) {
          for (let x = x1; x <= x2 && !found; x++) found = reachable.has(key(x, y));
        }
      }
      expect(found, `room ${r.id} has no reachable tile`).toBe(true);
    }
  });

  it('CA-11: desks of the 16 fixed agents in escritorio.proposta.json exist and are not vacancies', () => {
    const proposal = readJson(
      '../../../docs/projeto/2026-11-12-escritorio-equipe/escritorio.proposta.json',
    );
    const wanted = collectDeskIds((proposal as { agents?: unknown }).agents);
    expect(wanted).toHaveLength(16);
    const desks = new Map(map.desks.map((d) => [d.id, d]));
    for (const id of wanted) {
      const d = desks.get(id);
      expect(d, `desk ${id} missing from map`).toBeDefined();
      expect(d?.vacancy, `desk ${id} flagged as vacancy`).toBe(false);
    }
  });

  it('CA-21: each department has its free desks (-Vn); provisional desks and 14+ meeting seats exist', () => {
    const vacancies = map.desks.filter((d) => d.vacancy === true && d.department);
    const byDept = new Map<string, number>();
    for (const d of vacancies)
      byDept.set(d.department as string, (byDept.get(d.department as string) ?? 0) + 1);
    expect(Object.fromEntries(byDept)).toEqual({
      planejamento: 1,
      engenharia: 3,
      qualidade: 3, // QUA-V1, QUA-V2 and SOC-V1 (SOC belongs to the "qualidade" department)
      entrega: 1,
      biblioteca: 1,
    });
    expect(map.desks.filter((d) => d.id.startsWith('FL-D'))).toHaveLength(2);
    expect(map.seats.filter((s) => s.kind === 'meeting').length).toBeGreaterThanOrEqual(14);
    expect(map.seats.filter((s) => s.kind === 'project')).toHaveLength(24);
  });
});
